If you tell people what plugins you tried, maybe someone can recommend something else.
But if you want to show it with your display text plugin, I assume you can modify the gainItem method and make your plugin show the notification there. Something like this:
const _myEdit1_GameParty_gainItem = Game_Party.prototype.gainItem;
Game_Party.prototype.gainItem = function(item, amount, includeEquip) {
_myEdit1_GameParty_gainItem.call(this, item, amount, includeEquip);
if (SceneManager._scene instanceof Scene_Map && amount > 0) {
const itemName = item.name;
// CODE CODE CODE to show message with your plugin
}
};

